/* Resolve a bare filename from the spec to the LMS path convention.
   Files starting with a CP* code live in content/<CP>/; everything
   else lives in content/<COURSE_ID>/. URLs pass through unchanged. */
function resolveSrc(file, courseId) {
  if (!file || /^https?:/i.test(file)) return file;
  const trimmed = file.trim();
  const cpMatch = trimmed.match(/^(CP\d+)/i);
  if (cpMatch) return 'content/' + cpMatch[1].toUpperCase() + '/' + trimmed;
  return 'content/' + courseId + '/' + trimmed;
}

function buildCourse(id, spec) {
  let estimatedHours = 0;
  const screens = spec.rows.map((row, i) => {
    const [type, hours, title, file] = row;
    const src = resolveSrc(file, id);
    estimatedHours += Number(hours) || 0;
    const screen = {
      id: id.toLowerCase().replace(/^co0+/, 'co') + '-s' + String(i + 1).padStart(2, '0'),
      type: type,
      title: title,
      hours: hours,
      equipment: EQUIPMENT,
      src: src
    };
    /* Flag files we don't ship yet so the missing-resource UI fires.
       URLs are assumed reachable. */
    const isUrl = /^https?:/i.test(src);
    if (!isUrl) {
      const localPath = path.resolve(__dirname, '..', src);
      if (!fs.existsSync(localPath)) {
        screen.missing = true;
        if (type === 'image') {
          screen.thumbnail = 'content/' + id + '/opening.svg';
        }
      }
    }
    return screen;
  });
  return {
    id: id,
    code: id,
    kind: 'course',
    title: spec.title,
    shortDescription: spec.shortDescription,
    estimatedHours: Math.round(estimatedHours * 10) / 10,
    certificate: spec.certificate,
    screens: screens,
    categories: spec.categories
  };
}

function main() {
  const existing = fs.existsSync(COURSES_JSON)
    ? JSON.parse(fs.readFileSync(COURSES_JSON, 'utf8'))
    : { courses: [] };

  const courses = [];
  /* Rebuild every CO course from the spec */
  for (const id of Object.keys(COURSE_SPECS)) {
    const c = buildCourse(id, COURSE_SPECS[id]);
    courses.push(c);
    console.log('  built ' + id + ' (' + c.screens.length + ' screens, ' + c.estimatedHours + 'h)');
  }
  /* Preserve CP curriculum packs verbatim — they're hidden from the catalog
     for the May product direction but the data is kept so SCORM zips and
     content/CPxxxx/ folders still resolve. */
  for (const c of existing.courses) {
    if (/^CP/.test(c.id)) {
      if (c.kind !== 'pack') c.kind = 'pack';
      courses.push(c);
      console.log('  kept  ' + c.id + ' (pack, hidden from catalog)');
    }
  }
  fs.writeFileSync(COURSES_JSON, JSON.stringify({ courses }, null, 2) + '\n');
  console.log('\nWrote ' + courses.length + ' entries to data/courses.json');
}

main();
